using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.Remoting.Messaging;
using System.Runtime.Remoting.Proxies;
using Microsoft.Xrm.Sdk;
using Oiac.Engage.SiteActivityLog;
class SiteActivityLogNativeProvenanceTests {
 static readonly Guid Actor=Guid.NewGuid(),User=Guid.NewGuid(),Initiating=Guid.NewGuid(),Org=new Guid("3f613eb3-72ea-f011-aa23-6045bd003f09");
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);}
 static int Main(){try{Run();Console.WriteLine("PASS v2 native source/receipt binding, observed async ancestry, all implemented commands, forgery/replay/cascade negatives and zero SDK calls");return 0;}catch(Exception e){Console.WriteLine("FAIL "+e.Message);return 1;}}
 internal static Pair Make(string table="mss_activitypost",string message="Create",string command="post"){
  var p=new Pair();foreach(var c in new[]{p.Source,p.Api,p.Async}){c.V["OrganizationId"]=Org;c.V["UserId"]=User;c.V["InitiatingUserId"]=Initiating;c.V["CorrelationId"]=p.Correlation;c.V["PrimaryEntityId"]=p.Id;c.V["PrimaryEntityName"]=table;c.V["SharedVariables"]=new ParameterCollection();}
  p.Source.V["Mode"]=0;p.Source.V["Stage"]=20;p.Source.V["Depth"]=2;p.Source.V["MessageName"]=message;p.Source.V["ParentContext"]=p.Api.Proxy;
  p.Source.Input["Target"]=message=="Delete"?(object)new EntityReference(table,p.Id):new Entity(table,p.Id);p.Api.V["MessageName"]=table=="mss_appointment"?"mss_AppointmentCommand":"mss_ActivityChannelCommand";p.Api.V["Mode"]=0;p.Api.V["Stage"]=30;p.Api.V["Depth"]=1;p.Api.Input["ActorContactId"]=Actor;p.Api.Input["Command"]=command;
  p.Async.V["Mode"]=1;p.Async.V["Stage"]=40;p.Async.V["Depth"]=2;p.Async.V["MessageName"]=message;return p;
 }
 internal static void Stamp(Pair p){new SiteActivityLogNativeProvenancePlugin().Execute(new Provider(p.Source.Proxy));p.Async.V["SharedVariables"]=p.Source.V["SharedVariables"];}
 static bool Trusted(Pair p){Guid actor;string command;return SiteActivityLogCapturePlugin.Trusted(p.Async.Proxy,out actor,out command);}
 static Entity Receipt(Pair p){return (Entity)((ParameterCollection)p.Source.V["SharedVariables"])[SiteActivityLogNativeReceipt.Key];}
 static void Run(){
  foreach(var row in new[]{new[]{"mss_activitypost","Create","post"},new[]{"mss_activitypost","Update","pin"},new[]{"mss_activitypost","Update","unpin"},new[]{"mss_activitypost","Delete","remove"},new[]{"mss_activitycomment","Create","comment"},new[]{"mss_activitycomment","Create","reply"},new[]{"mss_activitycomment","Delete","remove"},new[]{"mss_appointment","Create","create"},new[]{"mss_appointment","Update","accept"},new[]{"mss_appointment","Update","reschedule"}}){var p=Make(row[0],row[1],row[2]);var original=p.Source.Input["Target"];Stamp(p);Check(Trusted(p),"supported command "+row[0]+"/"+row[1]+"/"+row[2]);Check(object.ReferenceEquals(original,p.Source.Input["Target"]),"Target unchanged");}
  var observed=Make();Stamp(observed);var rewritten=new Context();rewritten.V["MessageName"]="Create";rewritten.V["Mode"]=1;rewritten.V["Stage"]=30;rewritten.Input["ActorContactId"]=Guid.NewGuid();observed.Async.V["ParentContext"]=rewritten.Proxy;Check(Trusted(observed),"observed rewritten async ancestors do not invalidate self receipt");Guid actor;string command;Check(SiteActivityLogCapturePlugin.Trusted(observed.Async.Proxy,out actor,out command)&&actor==Actor&&command=="post","actor derives only from receipt");
  var systemDelete=ObservedDelete();Stamp(systemDelete);Check(Trusted(systemDelete),"observed exact-UAT SYSTEM Delete wrapper must preserve explicit remove history");
  foreach(string negative in new[]{"sourceUser","apiUser","wrapperUser","payloadId","missingPayload","extraPayload","otherMessage"}){var p=ObservedDelete();if(negative=="sourceUser")p.Source.V["UserId"]=Guid.NewGuid();if(negative=="apiUser")p.Api.V["UserId"]=Guid.NewGuid();if(negative=="wrapperUser"){var observedWrapper=(Context)p.Source.V["TestWrapper"];observedWrapper.V["UserId"]=Guid.NewGuid();}if(negative=="payloadId")p.Api.Input["Payload"]="{\"id\":\""+Guid.NewGuid()+"\",\"expectedRowVersion\":\"123\"}";if(negative=="missingPayload")p.Api.Input.Remove("Payload");if(negative=="extraPayload")p.Api.Input["Payload"]="{\"id\":\""+p.Id+"\",\"expectedRowVersion\":\"123\",\"actor\":\"forged\"}";if(negative=="otherMessage")p.Source.V["MessageName"]="Update";Stamp(p);Check(!Trusted(p),"SYSTEM switch exception rejects "+negative);}
  var input=Make();input.Async.Input["ActorContactId"]=Actor;input.Async.V["ParentContext"]=input.Api.Proxy;((ParameterCollection)input.Async.V["SharedVariables"])["tag"]="{actor:forged,api:mss_ActivityChannelCommand}";Check(!Trusted(input),"input actor and API tag cannot mint receipt");
  var ancestorOnly=Make();Stamp(ancestorOnly);ancestorOnly.Api.V["SharedVariables"]=ancestorOnly.Source.V["SharedVariables"];ancestorOnly.Async.V["SharedVariables"]=new ParameterCollection();ancestorOnly.Async.V["ParentContext"]=ancestorOnly.Api.Proxy;Check(!Trusted(ancestorOnly),"ancestor receipt ignored");
  foreach(string field in new[]{"record","site","organization","user","initiating","correlation"}){var p=Make();Stamp(p);Receipt(p)[field]=Guid.NewGuid();Check(!Trusted(p),"wrong receipt "+field+" rejected");}
  foreach(var change in new[]{new[]{"table","mss_activitycomment"},new[]{"message","Delete"},new[]{"api","mss_AppointmentCommand"},new[]{"command","remove"}}){var p=Make();Stamp(p);Receipt(p)[change[0]]=change[1];Check(!Trusted(p),"wrong receipt "+change[0]+" rejected");}
  var replay=Make();Stamp(replay);replay.Async.V["CorrelationId"]=Guid.NewGuid();Check(!Trusted(replay),"cross-request replay denied");var weak=Make();Stamp(weak);Receipt(weak)["actor"]=Actor.ToString("D");Check(!Trusted(weak),"string actor receipt rejected");var extra=Make();Stamp(extra);Receipt(extra)["payload"]="forged";Check(!Trusted(extra),"extra receipt field rejected");
  var nonnative=Make();nonnative.Api.V["MessageName"]="Create";Stamp(nonnative);Check(!Trusted(nonnative),"nonnative ancestor rejected");var wrongMode=Make();wrongMode.Api.V["Mode"]=1;Stamp(wrongMode);Check(!Trusted(wrongMode),"async ancestor cannot source stamp");var targetMismatch=Make();targetMismatch.Source.Input["Target"]=new Entity("mss_activitycomment",targetMismatch.Id);Stamp(targetMismatch);Check(!Trusted(targetMismatch),"wrong Target entity rejected");
  var cascade=Make("mss_activitycomment","Delete","remove");var wrapper=new Context();foreach(var key in new[]{"OrganizationId","UserId","InitiatingUserId","CorrelationId"})wrapper.V[key]=cascade.Source.V[key];wrapper.V["MessageName"]="Delete";wrapper.V["PrimaryEntityName"]="mss_activitypost";wrapper.V["PrimaryEntityId"]=Guid.NewGuid();wrapper.V["Mode"]=0;wrapper.V["Stage"]=30;wrapper.V["ParentContext"]=cascade.Api.Proxy;wrapper.Input["Target"]=new EntityReference("mss_activitypost",Guid.NewGuid());cascade.Source.V["ParentContext"]=wrapper.Proxy;Stamp(cascade);Check(!Trusted(cascade),"cascade delete is not another user action");
  var oldProof=Make();((ParameterCollection)oldProof.Async.V["SharedVariables"])[SiteActivityLogStampReceipt.Key]=new Entity(SiteActivityLogStampReceipt.EntityName);Check(!Trusted(oldProof),"marker v1 receipt cannot authorize production");
  foreach(string key in new[]{"OrganizationId","UserId","InitiatingUserId","CorrelationId"}){var p=Make();p.Api.V[key]=Guid.NewGuid();Stamp(p);Check(!Trusted(p),"source ancestor "+key+" mismatch rejected");}
  Check(!Trusted(Make("mss_appointment","Delete","remove")),"unimplemented appointment delete excluded");
 }
 static Pair ObservedDelete(){var p=Make("mss_activitypost","Delete","remove");var system=new Guid("e57ba9cc-171d-48f4-91e8-2fd1aece82f8");p.Source.V["UserId"]=system;p.Async.V["UserId"]=system;p.Api.V["UserId"]=Initiating;p.Api.Input["Payload"]="{\"id\":\""+p.Id+"\",\"expectedRowVersion\":\"123\"}";var wrapper=new Context();foreach(var k in new[]{"OrganizationId","UserId","InitiatingUserId","CorrelationId","PrimaryEntityId","PrimaryEntityName"})wrapper.V[k]=p.Source.V[k];wrapper.V["MessageName"]="Delete";wrapper.V["Stage"]=30;wrapper.V["Mode"]=0;wrapper.Input["Target"]=new EntityReference("mss_activitypost",p.Id);wrapper.V["ParentContext"]=p.Api.Proxy;p.Source.V["ParentContext"]=wrapper.Proxy;p.Source.V["TestWrapper"]=wrapper;return p;}
 internal class Pair{public Context Source=new Context(),Api=new Context(),Async=new Context();public Guid Id=Guid.NewGuid(),Correlation=Guid.NewGuid();}
 class Provider:IServiceProvider{IPluginExecutionContext Context;public Provider(IPluginExecutionContext c){Context=c;}public object GetService(Type type){if(type!=typeof(IPluginExecutionContext))throw new Exception("stamp must not request SDK service");return Context;}}
 internal class Context:RealProxy{public Dictionary<string,object> V=new Dictionary<string,object>();public ParameterCollection Input=new ParameterCollection();public IPluginExecutionContext2 Proxy{get{return (IPluginExecutionContext2)GetTransparentProxy();}}public Context():base(typeof(IPluginExecutionContext2)){}public override IMessage Invoke(IMessage raw){var call=(IMethodCallMessage)raw;string name=call.MethodName.Substring(4);object value=null;if(name=="InputParameters")value=Input;else V.TryGetValue(name,out value);var type=((System.Reflection.MethodInfo)call.MethodBase).ReturnType;if(value==null&&type.IsValueType)value=Activator.CreateInstance(type);return new ReturnMessage(value,null,0,call.LogicalCallContext,call);}}
}
